chapter(22, 'Compliance calendar and the assistant', 'Read the compliance calendar with its Action Center and firm profile, then ask the management assistant a question and read the anomaly flags.',
        'Farhan (Accountant)', 'accountant', menu='Accounts & Reports > Compliance calendar')
step('Farhan is on Modules Home. Tax and licence due dates are tracked in the Compliance calendar so that none is missed.', 'A missed GST or TDS date costs the hotel interest and penalty.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:accountant'], action='read', expect='Modules Home for Farhan.', check="ctx.uid==='accountant'")
tile('Accounts & Reports', 'Click the Accounts & Reports tile.', 'The calendar and the assistant are listed next to the accounting tiles.', expect='The Accounts & Reports page opens.')
leaf('Accounts & Reports', 'Compliance calendar', 'Click the Compliance calendar tile.', 'It lists the obligations of the financial year month by month.', expect='The Compliance calendar opens on October 2026.', check="ctx.page==='compliance'")
read('October 2026 lists cards such as the TDS deposit for September, the TDS return for the second quarter, the income tax filing for audit cases and the GSTR-1 for September. Each card has its due date and its status. The tabs run April to March, and the Dashboard tab summarises the year.', 'The calendar is built from the hotel\'s own profile, so it lists only what applies.', target='sel:main h1', expect='The obligations of October.')
click('btn:Action Center', 'Click Action Center. It shows the eleven items that need action.', 'The Action Center is the short list: overdue and due-soon cards, with the amount payable worked out from HCC data.', expect='The Action Center opens.')
click('btn:Firm profile', 'Click Firm profile.', 'The firm profile holds the GSTIN, the registrations and the licence expiry dates that drive the calendar, including the FSSAI and lodging licence renewals.', expect='The firm profile opens.')
press('Escape', 'Press Escape to close the profile.', 'Nothing changes until you save.', target='sel:main h1', expect='The calendar is shown.')
click('tab:Dashboard', 'Open the Dashboard tab.', 'The dashboard shows the count of obligations by status for the year.', expect='The compliance dashboard opens.')
click('btn:CSV register', 'Look at the buttons CSV register, Print month, Evidence ZIP, GSTR-1 working summary and CA pack.', 'The CA pack and the evidence zip give the accountant everything for the filing in one file; evidence files are attached to each card.', expect='The export buttons are on the page.')
step('Open Management assistant under Accounts & Reports. Sagar, the Owner, asks it questions about the hotel.', 'The assistant answers from the hotel\'s own data; it does not use the internet.', target='sel:main h1', auto=['key:Escape', 'user:owner', 'click:menutop:Accounts & Reports', 'click:menuleaf:Management assistant'], action='click', menu='Accounts & Reports > Management assistant', expect='The Management assistant opens.', check="ctx.page==='assistant'")
read('The page has a conversation box, suggested questions, the daily briefing and the anomaly flags. The suggested questions include Occupancy today, Next 7 days, Collections vs outstanding, Cash drawer, Pending approvals, Day-close readiness and Compliance due.', 'A question can be asked by clicking, so nobody has to remember the words.', target='btn:Occupancy today', expect='The suggested questions.')
click('btn:Occupancy today', 'Click Occupancy today.', 'The answer is worked out from the live room board.', expect='The assistant answers with today\'s occupancy.')
typ('field:Ask', 'How full are we tomorrow?', 'Type your own question: How full are we tomorrow?', 'The assistant understands a short question in plain English.', expect='The question is typed.')
click('btn:Ask', 'Click Ask.', 'The reply shows the number and the rooms behind it, with a Go there link to the screen.', expect='The assistant answers the question.')
click('btn:Daily briefing', 'Click Daily briefing.', 'The briefing is the owner\'s morning summary in a few lines.', expect='The daily briefing is shown.')
read('The Anomaly flags list unusual things: a big discount, many voids, a large cash difference, an advance that was never used. Each flag has Go there, which opens the screen to look at it.', 'The flags point at the entries worth a second look, so the owner needs no search.', target='btn:Go there', expect='The anomaly flags.')
